const __pageData = JSON.parse('{"title":"Week 16 solutions — spoilers","description":"","frontmatter":{"search":false,"prev":false,"next":false},"headers":[],"relativePath":"solutions/week-16.md","filePath":"solutions/week-16.md"}');
